import { PersonalReminderInputSchema, IdSchema } from '@cornerstone/contracts';
import { addCalendarDays } from './calendar.js';
import { DomainError } from './errors.js';

// RFC 5545 section 3.1: octets, not UTF-16 code units; continuation whitespace counts.
export function foldCalendarLine(line: string): string {
  if (/[\u0000-\u001f\u007f]/u.test(line))
    throw new DomainError(
      'INVALID_CALENDAR_LINE',
      'A calendar content line cannot contain controls.',
    );
  const encoder = new TextEncoder();
  const lines: string[] = [];
  let current = '',
    width = 0;
  for (const character of line) {
    const bytes = encoder.encode(character).length;
    if (width + bytes > 75) {
      lines.push(current);
      current = ' ';
      width = 1;
    }
    current += character;
    width += bytes;
  }
  return [...lines, current].join('\r\n');
}

/** Deliberately accepts no record, contact, location, URL, free text or deadline claim. */
export function personalCalendarReminder(input: unknown): string {
  const { date } = PersonalReminderInputSchema.parse(input);
  const end = addCalendarDays(date, 1); // Validates actual dates and rejects year overflow.
  const uid = IdSchema.parse(crypto.randomUUID());
  const stamp = new Date()
    .toISOString()
    .replace(/[-:]/g, '')
    .replace(/\.\d{3}Z$/, 'Z');
  if (!/^\d{8}T\d{6}Z$/.test(stamp))
    throw new DomainError('INVALID_CALENDAR_CLOCK', 'The calendar export clock is unavailable.');
  return (
    [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//The Cornerstone//Personal preparation reminder//EN',
      'CALSCALE:GREGORIAN',
      'BEGIN:VEVENT',
      `UID:urn:uuid:${uid}`,
      `DTSTAMP:${stamp}`,
      `DTSTART;VALUE=DATE:${date.replaceAll('-', '')}`,
      `DTEND;VALUE=DATE:${end.replaceAll('-', '')}`,
      'SUMMARY:Personal preparation reminder',
      'DESCRIPTION:Personal reminder only. Not legal service or an official deadline. Open your workspace separately and verify any applicable requirements. Set notifications in your calendar yourself.',
      'CLASS:PRIVATE',
      'TRANSP:TRANSPARENT',
      'END:VEVENT',
      'END:VCALENDAR',
    ]
      .map(foldCalendarLine)
      .join('\r\n') + '\r\n'
  );
}

'use client';
import { useEffect, useRef, useState, type FormEvent } from 'react';
import { personalCalendarReminder } from '@cornerstone/domain';

export function ReminderPanel({
  recordId,
  api,
  disabled = false,
}: {
  recordId: string;
  api: (path: string, body?: unknown) => Promise<any>;
  disabled?: boolean;
}) {
  const [date, setDate] = useState('');
  const [consent, setConsent] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const generation = useRef(0);
  const busyRef = useRef(false);
  const prepared = useRef<{ date: string; content: string } | null>(null);
  useEffect(() => {
    generation.current++;
    return () => {
      generation.current++;
      prepared.current = null;
    };
  }, []);

  async function prepare(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (busyRef.current || disabled || !consent) return;
    const current = generation.current;
    busyRef.current = true;
    setBusy(true);
    setError('');
    setMessage('');
    try {
      // Validate before requesting anything, but do not produce a file until current access passes.
      const content =
        prepared.current?.date === date
          ? prepared.current.content
          : personalCalendarReminder({ date, consent });
      const result = await api('records?recordId=' + encodeURIComponent(recordId));
      if (generation.current !== current) return;
      if (!result?.records?.some((record: { id: string }) => record.id === recordId))
        throw Error('Current record access could not be verified. No reminder was exported.');
      prepared.current = { date, content };
      const url = URL.createObjectURL(new Blob([content], { type: 'text/calendar;charset=utf-8' }));
      const link = document.createElement('a');
      try {
        link.href = url;
        link.download = 'preparation-reminder.ics';
        document.body.append(link);
        link.click();
      } finally {
        link.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
      }
      setMessage(
        'Calendar file prepared. Import it into a private calendar and choose notification settings there. No calendar delivery or legal deadline has been confirmed.',
      );
    } catch (e) {
      if (generation.current === current)
        setError(e instanceof Error ? e.message : 'The reminder could not be exported.');
    } finally {
      busyRef.current = false;
      if (generation.current === current) setBusy(false);
    }
  }
  return (
    <details className="saved-details">
      <summary>Personal calendar reminder</summary>
      <form className="form-stack" onSubmit={(event) => void prepare(event)}>
        <p className="muted">
          Choose a date to remind yourself to review your preparation. This is not legal service or
          an official deadline. Nothing is sent to a calendar automatically.
        </p>
        <div className="field">
          <label htmlFor="personal-reminder-date">Reminder date</label>
          <input
            id="personal-reminder-date"
            type="date"
            required
            min="1000-01-01"
            max="9999-12-30"
            value={date}
            disabled={busy || disabled}
            onChange={(event) => {
              setDate(event.target.value);
              setMessage('');
              setError('');
            }}
          />
        </div>
        <label className="check-label">
          <input
            type="checkbox"
            checked={consent}
            disabled={busy || disabled}
            onChange={(event) => {
              setConsent(event.target.checked);
              setMessage('');
            }}
          />
          I understand that my calendar provider or people with calendar access may see this generic
          reminder and my use of this tool.
        </label>
        <p className="hint">
          The file has a generic title, date, random event identifier and software name. It excludes
          case titles, record identifiers, private text, contacts and links. Imported copies cannot
          be recalled by this workspace; a calendar may ignore its private classification. Repeated
          downloads here reuse the event identifier, but calendar import behavior varies.
        </p>
        <button
          className="button button-secondary"
          disabled={busy || disabled || !date || !consent}
        >
          {busy ? 'Preparing reminder...' : 'Download calendar reminder'}
        </button>
        {error && (
          <p className="error-panel" role="alert">
            {error}
          </p>
        )}
        {message && (
          <p className="hint" role="status">
            {message}
          </p>
        )}
      </form>
    </details>
  );
}

