import { test, expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import { randomUUID } from 'node:crypto';
import { readFile } from 'node:fs/promises';

test('personal reminder export requires consent and current access and excludes case data', async ({
  page,
}, info) => {
  await page.goto('/');
  await page
    .getByRole('button', { name: 'participant \u00b7 synthetic development', exact: true })
    .click();
  await expect(page.getByRole('heading', { name: 'Your next step, made clear.' })).toBeVisible();
  const me = await (await page.request.get('/api/private/me')).json();
  const response = await page.request.post('/api/private/records', {
    headers: { Origin: 'http://127.0.0.1:3001', 'X-CSRF-Token': me.csrf },
    data: {
      kind: 'dossier',
      title: 'Invented private calendar case ' + randomUUID(),
      input: {
        actionDescription: 'Invented private action',
        livelihood: 'Invented private job',
        lossDescription: 'Invented private loss',
      },
      idempotencyKey: randomUUID(),
    },
  });
  expect(response.status()).toBe(201);
  const record = (await response.json()).record;
  await page.reload();
  await page
    .locator('.task-card')
    .filter({ has: page.getByRole('heading', { name: record.title, exact: true }) })
    .getByRole('button', { name: 'Open', exact: true })
    .click();
  await page.getByText('Personal calendar reminder', { exact: true }).click();
  const button = page.getByRole('button', { name: 'Download calendar reminder', exact: true });
  await expect(button).toBeDisabled();
  await page.getByLabel('Reminder date', { exact: true }).fill('2028-02-29');
  await expect(button).toBeDisabled();
  await page.getByRole('checkbox', { name: /^I understand that my calendar provider/ }).check();
  let downloads = 0;
  page.on('download', () => downloads++);
  const pending = page.waitForEvent('download');
  await button.click();
  const file = await pending;
  expect(file.suggestedFilename()).toBe('preparation-reminder.ics');
  const content = await readFile((await file.path())!, 'utf8');
  expect(content).toContain('DTSTART;VALUE=DATE:20280229');
  expect(content).toContain('DTEND;VALUE=DATE:20280301');
  expect(content).not.toContain(record.id);
  expect(content).not.toContain(record.title);
  expect(content).not.toContain(me.actor.id);
  expect(content).not.toContain('Invented private');
  await expect(
    page.getByRole('status').filter({ hasText: 'Calendar file prepared.' }),
  ).toBeVisible();
  const repeated = page.waitForEvent('download');
  await button.click();
  expect(await readFile((await (await repeated).path())!, 'utf8')).toBe(content);
  await page.route('**/api/private/records?recordId=*', (route) =>
    route.fulfill({
      status: 403,
      contentType: 'application/json',
      body: JSON.stringify({ message: 'Current record access is unavailable.' }),
    }),
  );
  await button.click();
  await expect(
    page.getByRole('alert').filter({ hasText: 'Current record access is unavailable.' }),
  ).toBeVisible();
  expect(downloads).toBe(2);
  await page.unroute('**/api/private/records?recordId=*');
  const a11y = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21aa']).analyze();
  expect(a11y.violations.map((v) => v.id)).toEqual([]);
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1)).toBe(
    true,
  );
  await page.getByText('Personal calendar reminder', { exact: true }).scrollIntoViewIfNeeded();
  await page.screenshot({
    path: `test-results/private-reminder-${info.project.name}.png`,
    fullPage: true,
  });
  let release!: () => void, captured!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  const reached = new Promise<void>((resolve) => {
    captured = resolve;
  });
  await page.route('**/api/private/records?recordId=*', async (route) => {
    const reply = await route.fetch();
    captured();
    await gate;
    await route.fulfill({ response: reply });
  });
  await button.click();
  await reached;
  await page.getByRole('button', { name: 'Back to records', exact: true }).click();
  const late = page.waitForResponse((r) => r.url().includes('/api/private/records?recordId='));
  release();
  await late;
  await expect(page.getByText('Personal calendar reminder', { exact: true })).toHaveCount(0);
  await page.waitForTimeout(250); // Allows the held JSON continuation to execute after unmount.
  expect(downloads).toBe(2);
  expect(await page.evaluate(() => localStorage.length)).toBe(0);
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { foldCalendarLine, personalCalendarReminder } from '@cornerstone/domain';
const unfold = (text: string) => text.replace(/\r\n[ \t]/g, '');
afterEach(() => {
  vi.useRealTimers();
  vi.restoreAllMocks();
});

describe('privacy-minimal personal calendar export', () => {
  it.each([
    ['2028-02-29', '20280301'],
    ['2026-12-31', '20270101'],
    ['2026-03-08', '20260309'],
    ['9999-12-30', '99991231'],
  ])('uses all-day dates with an exclusive end: %s', (date, end) => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-10-12T14:00:00.123Z'));
    const raw = personalCalendarReminder({ date, consent: true });
    const lines = unfold(raw).split('\r\n');
    expect(lines).toContain('DTSTART;VALUE=DATE:' + date.replaceAll('-', ''));
    expect(lines).toContain('DTEND;VALUE=DATE:' + end);
    expect(lines).toContain('DTSTAMP:20261012T140000Z');
    expect(lines.filter((line) => line === 'BEGIN:VEVENT')).toHaveLength(1);
    expect(lines.filter((line) => line.startsWith('UID:urn:uuid:'))).toHaveLength(1);
    expect(raw.endsWith('\r\n')).toBe(true);
    for (const line of raw.split('\r\n'))
      expect(new TextEncoder().encode(line).length).toBeLessThanOrEqual(75);
    expect(raw.replaceAll('\r\n', '')).not.toMatch(/[\r\n]/);
    expect(lines).not.toContain('METHOD:REQUEST');
    expect(raw).not.toMatch(/ATTENDEE|ORGANIZER|LOCATION|VALARM|URL:|TZID|TRIGGER/);
    expect(unfold(raw)).toContain('Not legal service or an official deadline.');
  });
  it.each([
    '2027-02-29',
    '2026-04-31',
    '9999-12-31',
    '0001-01-01',
    '2026-10-12\r\nATTENDEE:attacker@example.test',
  ])('rejects invalid dates and property injection: %s', (date) => {
    expect(() => personalCalendarReminder({ date, consent: true })).toThrow();
  });
  it.each([false, undefined, 'true', 1])('requires explicit consent: %s', (consent) => {
    expect(() => personalCalendarReminder({ date: '2026-10-13', consent })).toThrow();
  });
  it.each(['recordId', 'title', 'description', 'email', 'url', 'uid', 'legalService'])(
    'rejects extra private or authority-bearing input: %s',
    (field) => {
      expect(() =>
        personalCalendarReminder({ date: '2026-10-13', consent: true, [field]: 'not accepted' }),
      ).toThrow();
    },
  );
  it('does not derive event identifiers from a record or date', () => {
    const first = unfold(personalCalendarReminder({ date: '2026-10-13', consent: true }));
    const second = unfold(personalCalendarReminder({ date: '2026-10-13', consent: true }));
    expect(first.match(/^UID:.+$/m)?.[0]).not.toBe(second.match(/^UID:.+$/m)?.[0]);
  });
  it('folds UTF-8 at complete characters, including continuation spaces', () => {
    const text = 'SUMMARY:' + 'A'.repeat(65) + '\u{1f331}'.repeat(30) + '\u00e9'.repeat(12);
    const folded = foldCalendarLine(text);
    expect(unfold(folded)).toBe(text);
    for (const line of folded.split('\r\n'))
      expect(new TextEncoder().encode(line).length).toBeLessThanOrEqual(75);
  });
  it.each(['\nBEGIN:VEVENT', '\r\nATTENDEE:x', 'A\u0000B'])(
    'refuses control characters before folding',
    (line) => {
      expect(() => foldCalendarLine(line)).toThrow();
    },
  );
});
